# ===================== 机器人新闻 1-3 =====================
机器人 = [
 ("智元发布AGILE2.0·从“盲动”到“边看边想边动”", "9月9日，" + H(RED, "智元发布AGILE2.0感控一体模型（AGIBOT Generative Intelligent Locomotion Engine）") + "，" + H(ORANGE, "人形机器人的运动控制正在尝试告别机械的“盲动”，开始“边看、边想、边动”") + "。它的意义在于" + H(CYAN, "把人形机器人运动控制从分段式架构推向端到端感控一体，有望让机器人像人一样实现视觉、理解与动作同步，从根本上解决“所见非所动”的痛点") + "。但" + H(GREEN, "端到端模型对数据、算力、安全冗余的要求更高，任何一次“眼脑手”不同步都可能导致任务失败") + "，" + H(GREEN, "具身智能要真正“干活”，还需在真实产线里经受长期磨练") + "。资本侧同样活跃：" + H(RED, "优地机器人9月9日在港交所上市首日大涨153.84%") + "，成为当日港股最大亮点。"),
 ("具身智能的数据基础设施：无本体数据先行", "具身智能长期被" + H(GREEN, "“数据荒漠”") + "困扰，近期有了基础设施层面的进展。位于张江机器人谷的" + H(RED, "觅蜂科技完成2万套无本体数据采集设备下线，并累计生产超过100万小时高质量无本体数据，成为行业第一家达成该规模的企业") + "。" + H(ORANGE, "无本体数据的价值在于把“造机器”和“喂数据”两件事拆开：采集端可以先把规模做起来，不必等本体量产之后再回头补数据，等于把最耗时间的一环提前了") + "。政策侧" + H(CYAN, "深圳市工信局、科创局已印发《深圳市推动智能机器人产业高质量发展工作方案（2026—2028年）》") + "；" + H(CYAN, "北京市人民政府印发《北京市“十五五”时期高精尖产业发展规划》，把具身智能机器人列入动能接续方阵") + "。" + H(GREEN, "数据规模一旦跨过门槛，算法迭代的瓶颈就从“数据不够”变成“场景与算力不够”，这是具身智能从演示走向量产的前置条件") + "。"),
 ("端侧AI与机器人协同：算力配置结构正在改变", "端侧AI正在成为新的竞争焦点。芯片侧" + H(RED, "Arm推出基于台积电N3P的128核Neoverse CSS N4（代号Ranger），面向云、网络与智能体AI负载") + "，" + H(RED, "华为推出麒麟9050 Pro，是时隔六年再度亮相的全新高性能麒麟芯片，整机性能较上代提升42%") + "；模型侧" + H(CYAN, "OpenBMB于9月7日发布MiniCPM5-2B，25亿参数端侧模型在34个基准上平均53.9分，登顶4B以下开源榜") + "。" + H(ORANGE, "端侧算力越强，机器人对云端的依赖就越低，这会反过来改变整个算力基础设施的配置结构——从集中式训练，走向训练集中、推理分散") + "。" + H(CYAN, "另一个值得注意的信号是：9月9日电力设备行业主力净流入16.66亿元，而AI应用类行业普遍净流出，资金已经在为“推理端的物理基础设施”定价") + "。"),
]
for i,(t,c) in enumerate(机器人,1):
    D["机器人新闻%d_标签和标题"%i] = t
    D["机器人新闻%d_正文"%i] = c

# ===================== AI应用新闻 1-3 =====================
AI应用 = [
 ("Meta推出Muse智能体·股价大涨6.55%", "在一片下跌的美股科技股里，Meta是唯一的亮点。" + H(RED, "当地时间9月8日Meta宣布推出一款名为Muse的新智能体，9月9日股价大涨6.55%") + "，而同期" + H(GREEN, "谷歌跌2.09%、亚马逊跌1.78%、英伟达跌0.91%、微软跌0.47%") + "，" + H(GREEN, "万得美国科技七巨头指数跌0.48%") + "。" + H(ORANGE, "同样是AI叙事，为什么只有Meta涨？差别在于它把Agent落到了自己已经拥有十亿级用户的产品里——分发渠道比模型能力更稀缺") + "。" + H(CYAN, "这一逻辑对国内应用同样成立：谁能把Agent接进已有的高频场景，谁才可能先跑出商业闭环") + "。"),
 ("苹果iPhone Duo发布·“利好兑现”剧本再次上演", H(CYAN, "苹果于北京时间9月10日凌晨1点举行秋季发布会，推出首款折叠屏手机iPhone Duo及新款iPhone等产品") + "，" + H(ORANGE, "这也是新任CEO约翰·特努斯首次主持秋季发布会，正式接棒已退休的蒂姆·库克") + "。市场此前关注的是" + H(CYAN, "折叠屏铰链良率、定价（普遍预期2000美元档位）及AI功能整合进展") + "。结果很有代表性——" + H(GREEN, "苹果当日股价小幅下跌0.28%") + "，" + H(GREEN, "“利好兑现即回落”的剧本再次上演") + "。A股果链的反应更值得观察：" + H(RED, "东山精密主力净流入19.25亿元、股价涨超5%，尾盘净流入3.38亿元居首") + "，" + H(ORANGE, "但这一流入发生在发布会之前，属于预期交易而非结果交易") + "。" + H(GREEN, "对供应链来说，真正的变量不是发布会当天，而是首销季的良率与备货量") + "。"),
 ("国内应用侧：服贸会上的AI全链路展示", "9月9日" + H(CYAN, "2026年中国国际服务贸易交易会在北京首钢园开幕，90个国家（地区）、国际组织设展办会，1800余家企业线下参展") + "，" + H(RED, "阿里专场发布会集中展示多项AI应用，覆盖电商种草、选购到售后全链路") + "。模型侧" + H(CYAN, "科大讯飞已发布星火X2.5大模型，采用MoE架构、参数规模293B-A30B，重点提升代码与智能体能力，基于全国产算力完成全流程训练及推理") + "。" + H(ORANGE, "一边是展会上的全链路应用，一边是国产算力训出来的新模型——两件事共同说明，国产AI的评价标准已从跑分转向能否嵌进真实业务流程") + "。另一侧，" + H(CYAN, "人力资源社会保障部等部门9月9日发布11个新职业、23个新工种，调整变更农产品经纪人等6个职业信息") + "，" + H(GREEN, "职业目录的更新速度，本身就是技术扩散最诚实的指标") + "。"),
]
for i,(t,c) in enumerate(AI应用,1):
    D["AI应用新闻%d_标签和标题"%i] = t
    D["AI应用新闻%d_正文"%i] = c

# ===================== 生物医学工程 5 张卡 =====================
D["生物医学_政策_标签和标题"] = "政策·北京把脑机接口写进“十五五”高精尖规划"
D["生物医学_政策_正文"] = "9月9日" + H(CYAN, "北京市人民政府印发《北京市“十五五”时期高精尖产业发展规划》") + "，明确" + H(RED, "聚焦未来信息、未来健康、未来制造、未来能源、未来材料、未来空间六个方向，构建“动能接续、潜能激发、前瞻引领”的未来产业成长方阵") + "。其中" + H(RED, "潜能激发方阵以工程化组织、场景验证为重点，加速量子科技、脑机接口、第六代移动通信（6G）等领域新产品创制") + "；" + H(CYAN, "动能接续方阵则持续推动具身智能机器人、氢能、生物制造成为新的经济增长点") + "。此前" + H(CYAN, "“十五五”规划已将脑机接口列为六大未来产业之一") + "。" + H(ORANGE, "把脑机接口与量子科技、6G放在同一个方阵，意味着监管层给它的定位是“需要工程化验证的未来产业”，而不是可以马上放量的消费赛道") + "。同一时间窗口里还有一条更贴近终端的政策：" + H(RED, "9月5日至8日国家医保局组织开展2026年国家基本医保药品目录现场谈判竞价，上百家内外资企业参与，124个目录外药品入围谈判竞价环节") + "，" + H(CYAN, "肿瘤、罕见病、慢性病与儿童用药等重点领域创新药参与谈判，并有望纳入医保目录") + "；" + H(RED, "商业健康保险创新药品目录调整同步开展，12个药品入围现场价格协商") + "。" + H(ORANGE, "2026年国家医保药品目录与商保创新药目录预计11月发布、2027年1月1日起施行——从谈成到落地还有约两个月真空期，这段时间是创新药企估值最容易被情绪左右的阶段") + "。同日" + H(CYAN, "中银国际指出医药行业增长韧性十足、结构性修复持续演绎，维持强于大市评级") + "。"
D["生物医学_设备_标签和标题"] = "设备·创新医疗器械审查再添8项，含植入式无线脑机接口"
D["生物医学_设备_正文"] = "9月9日" + H(RED, "国家药监局医疗器械技术审评中心公示创新医疗器械特别审查申请审查结果（2026年第15号），拟同意8个项目进入特别审查程序，公示期为9月9日至9月23日") + "。名单里有两项直接与脑机接口相关：" + H(RED, "北京智冉医疗科技的“植入式无线脑机接口系统”，以及北京华科恒生医疗科技的“脑深部宏微电极”") + "；其余包括" + H(CYAN, "广州巧捷力医疗科技的膀胱内窥镜手术系统、微创神通与广东广纳安疗的液体栓塞剂、圣犹达的磁定位压力监测射频脉冲消融导管、先健科技的主动脉弓单分支覆膜支架系统、普瑞基准的人类同源重组修复缺陷检测试剂盒") + "。" + H(ORANGE, "进入创新审查程序不代表已认定产品具备可获准注册的安全有效性，但它是国产高端器械从“跟跑”到“并跑”的必经通道") + "。" + H(GREEN, "对投资者来说，这个名单的价值在于它提前半年到一年透露了下一个可能获批的产品方向") + "。"
D["生物医学_脑机接口_标签和标题"] = "脑机接口·从“水晶鞋”转向“旅游鞋”"
D["生物医学_脑机接口_正文"] = "产业侧正在出现一个重要的思路转向。清华大学医学院教授、" + H(CYAN, "中国神经工程和脑机接口学科主要创建者之一高小榕") + "在专访中打了个比方：" + H(ORANGE, "我们不能总拿着“水晶鞋”到处去找合适的脚，而是要先做出更方便的“旅游鞋”") + "。这句话指向的是" + H(RED, "技术驱动与需求驱动的分野——过去几年行业在比电极通道数、比信号质量，而现在要开始比“谁的临床场景更刚需、谁的产品更好用”") + "。产业进展确实在加速：" + H(RED, "2026年3月国家药监局批准博睿康的植入式脑机接口手部运动功能代偿系统注册，实现全球首个侵入式脑机接口医疗器械上市") + "；" + H(RED, "5月清华团队开发出厚度仅9微米的全有机超柔性脑皮层电极阵列，8月中科院理化所的多功能阳离子交替肽电极界面涂层实现脑内植入300天有效通道无衰减") + "。" + H(CYAN, "中国信通院数据显示2025年我国脑机接口市场规模约30亿元，预计2030年达120亿元") + "。"
D["生物医学_就业_标签和标题"] = "就业·11个新职业发布，技术扩散落到岗位上"
D["生物医学_就业_正文"] = "9月9日" + H(RED, "人力资源社会保障部等部门向社会发布11个新职业、23个新工种，并调整变更农产品经纪人等6个职业（工种）信息") + "。" + H(ORANGE, "新职业目录的更新节奏，是观察技术扩散最直接的窗口——它反映的不是实验室里发生了什么，而是企业里真的开始出现什么岗位") + "。与此形成对照的是另一端的压力：" + H(GREEN, "AI语料、短剧游戏、网络游戏等内容生产类概念在9月9日普遍跌逾2%，传媒行业主力净流出41.41亿元居首") + "，" + H(GREEN, "美股软件股继续承压，市场对生成式AI冲击垂直软件业务的担忧并未消退") + "。" + H(ORANGE, "同一项技术，在新场景里创造岗位、在旧场景里消减岗位——这不是矛盾，这就是技术扩散的常态") + "。" + H(GREEN, "落到个人身上，判断方法也不复杂：看你的工作是在按流程操作工具，还是在为工具设定要解决什么问题") + "。"
D["生物医学_安全_标签和标题"] = "安全·量子计算的双刃剑与AI自主性"
D["生物医学_安全_正文"] = "安全侧有两条并行的新闻。其一是量子：" + H(GREEN, "量子技术企业IonQ于9月8日表示，一台拥有约2万物理量子比特的离子阱量子计算机，或仅需约25.7天即可攻破比特币使用的secp256k1椭圆曲线签名加密") + "；同日" + H(CYAN, "IonQ发布第六代量子平台Superion 256，预计2027年交付客户") + "。" + H(ORANGE, "这意味着现有公钥体系的“安全剩余年限”第一次有了可计算的量级") + "。其二是AI自主性：" + H(GREEN, "OpenAI在系统卡中承认GPT-6 Astra思维链的可监控性明显下降") + "；" + H(CYAN, "最高人民法院已发布《关于依法审理涉人工智能纠纷案件的意见》，这是我国首部涉人工智能司法裁判规则文件") + "。" + H(ORANGE, "一边是算力突破逼近加密体系的边界，一边是模型自主性超出可解释范围——技术、司法、监管三条线正在同时收紧") + "。"

# ===================== 机构观点 6 家 =====================
D["机构1_名称"] = "中信建投证券"
D["机构1_标签"] = "策略·三方向聚焦"
D["机构1_简称"] = "中信建投"
D["机构1_观点"] = H(CYAN, "中信建投证券策略团队") + "在9月9日指出，" + H(RED, "科技板块仍是盈利增长最突出的方向，AI需求、硬件涨价构成主要驱动") + "。资源端的业绩弹性更大：" + H(RED, "有色金属行业上半年营收、利润分别增长27%和89%，基础化工、石油石化行业利润分别增长37%和34%") + "，" + H(ORANGE, "资源品涨价与供给约束持续转化为企业盈利") + "。建议聚焦三个方向：一是" + H(RED, "科技成长——全球AI资本开支与国产化持续兑现的光模块、高端PCB、高速铜连接、存储") + "；二是" + H(CYAN, "先进制造——需求保持韧性的储能、电池及优势制造业出海") + "；三是" + H(RED, "资源品——低库存、供给约束支撑的铜、铝、锡等有色金属，以及供需格局优化的煤炭") + "。" + H(RED, "这份清单与9月9日盘面吻合度极高：煤炭涨2.98%、有色涨1.49%双双领涨，通信净流入54.46亿元居首") + "。" + H(ORANGE, "翻译成操作语言：它给的是“三条腿”而不是“一条赛道”，这本身就是对快速轮动的回应") + "。"
D["机构2_名称"] = "中国银河证券"
D["机构2_标签"] = "煤炭·创多年新高"
D["机构2_简称"] = "中国银河"
D["机构2_观点"] = H(CYAN, "中国银河证券") + "研报数据显示：" + H(RED, "9月4日秦皇岛港5500大卡动力煤市场价962元/吨，环比前一周上涨81元/吨、同比上涨282元/吨，创2023年10月以来新高") + "；" + H(RED, "山西产主焦煤市场价2395元/吨，环比前一周上涨179元/吨、同比上涨1139元/吨，创2022年6月以来新高") + "。该机构判断" + H(ORANGE, "今年以来在印尼收紧出口、中东地缘冲突等因素影响下，煤价持续上涨") + "，建议关注两类标的：" + H(RED, "具备高现货占比、低成本优势及产能增长潜力的弹性标的") + "，以及" + H(RED, "具备资源储备、成本优势及高分红承诺的龙头公司") + "。" + H(CYAN, "该机构在光通信领域同时提示，光通信产业技术演进已迈入深水区，产业链价值重心正从传统光模块封装环节加速向光源、硅光芯片、精密耦合及高密度连接等底层核心器件扩散") + "。" + H(GREEN, "对以收息为目的的资金，后一类更值得看——明确的分红承诺能把周期股的价格起伏切掉一部分，换成可以按年预期的现金流") + "。"
D["机构3_名称"] = "国泰海通证券"
D["机构3_标签"] = "策略·扩散与均衡"
