# ===================== 老盛持仓分析（个人持仓快照·目标配比 国有:股份:城商=4:3:3） =====================
# 持仓股数为个人固定快照；现价取 2026-09-09 收盘（与报告标的卡一致）。类型归类：工行/农行=国有大行，招行=股份行，宁波/江苏/杭州=城商行。
_HOLDS = [
    ("工商银行", "601398", 127200, 8.00, "国有大行"),
    ("农业银行", "601288", 500, 6.81, "国有大行"),
    ("招商银行", "600036", 40000, 41.00, "股份行"),
    ("宁波银行", "002142", 10000, 34.66, "城商行"),
    ("江苏银行", "600919", 40000, 12.33, "城商行"),
    ("杭州银行", "600926", 20000, 17.28, "城商行"),
]
_HOLD_TOTAL = sum(sh * px for _, _, sh, px, _ in _HOLDS)
def _hp(v):
    return v / _HOLD_TOTAL * 100
_gg = sum(sh * px for _, _, sh, px, t in _HOLDS if t == "国有大行")
_gf = sum(sh * px for _, _, sh, px, t in _HOLDS if t == "股份行")
_cs = sum(sh * px for _, _, sh, px, t in _HOLDS if t == "城商行")
_ggp, _gfp, _csp = _hp(_gg), _hp(_gf), _hp(_cs)
_T = _gf / 0.30                       # 股份行不卖、稀释至30%时的目标总盘
_DA_GG = 0.40 * _T - _gg              # 国有大行需补金额
_DA_CS = 0.30 * _T - _cs              # 城商行需补金额
D["持仓分析_导语"] = ("截至2026-09-10，老盛A股持仓为" + H(CYAN, "6只银行、全部为银行股") + "。"
    + "当下结构" + H(ORANGE, f"国有大行占{_ggp:.1f}%、股份行占{_gfp:.1f}%、城商行占{_csp:.1f}%") + "，与目标" + H(RED, "国有:股份:城商=4:3:3") + "相比，" + H(GREEN, "股份行（主要是招行）超配、国有大行欠配") + "，这个错位仍是再平衡要解决的第一矛盾。9月9日银行板块由分化转为普涨，组合六只标的全线受益，其中工行涨0.76%、农行涨0.74%，国有大行这一块的拖累明显减轻。")
D["持仓分析_配比"] = ("目标 4:3:3 即国有 40%、股份 30%、城商 30%。现状国有 " + H(ORANGE, f"{_ggp:.1f}%") + "、股份 " + H(ORANGE, f"{_gfp:.1f}%") + "、城商 " + H(ORANGE, f"{_csp:.1f}%") + "——" + H(GREEN, f"股份行超配约 {_gfp-30:.0f} 个百分点、国有大行欠配约 {40-_ggp:.0f} 个百分点") + "。要向目标收敛，路径其实只有一条：招行不动，用新增资金把股份行占比稀释下来，同时把" + H(RED, "国有大行的比重往40%推") + "；城商行已经贴着30%的目标，能再给的额度不多。9月9日六只标的中工行与农行双双上涨，" + H(CYAN, "但补仓的顺序应该按缺口大小排，而不是按当天涨幅排") + "。")
D["持仓分析_分析"] = ("六只标的全部集中在银行股，之所以能拿得住，靠的是股息、估值与接近债券的现金流这三样东西共同构成的防线——" + H(CYAN, "高股息、低估值与类债现金流") + "这个防御阵地。9月9日值得记一笔的是" + H(ORANGE, "“分化转为普涨”") + "：前一天的大行让位，变成了" + H(RED, "16只关注标的13涨2跌1平（宁波平盘），工行涨0.76%重回8元、农行涨0.74%、招行涨0.24%，建行涨1.31%领涨国有大行") + "。原因不在银行内部，而在" + H(CYAN, "外部组合——布伦特突破100美元、美债10年期创2023年11月以来新高，在这个组合下资金第一反应是回到有确定性现金流的资产") + "。基本面的方向没有变化：" + H(RED, "二季度净息差1.41%也是四年来第一次单季转正") + "，" + H(RED, "42家银行上半年营收+7.4%、净利+2.96%") + "，" + H(RED, "六大行中期分红比例已提至31%") + "。短板也很明确：招行一只就占去组合的 " + H(ORANGE, f"{_gfp:.0f}%") + "，零售资产质量或市场风格一旦掉头，回撤会集中压在它一只上；宁波银行平盘、PB 0.97倍是城商行里最贵的一档；而" + H(GREEN, "农业银行的仓位薄到可以忽略，可它偏偏是配比上缺口最大的一块") + "。")
D["持仓分析_操作"] = ("顺序已经清楚了——" + H(RED, "加仓时把国有大行排在第一位，因为那一块欠得最多") + "：工行与农行受注资+分红提升双重催化、确定性最高，注资带来的摊薄已被市场在两天内消化，" + H(CYAN, "建议在回踩5日或10日线分批吸纳，把国有大行占比往40%推进") + "。" + H(GREEN, "招行不卖") + "、靠加仓自然稀释至30%，其ROE 6.71%与4.93%的股息率仍是核心底仓。" + H(ORANGE, "宁波银行PB已到0.97倍、前一日刚涨1.55%，不建议追高") + "；若坚持加城商行，额度更应给 " + H(CYAN, "江苏（股息率4.60%）与邮储（PB 0.62倍）") + "，但城商行已接近目标、边际额度有限。总仓位控在 " + H(CYAN, "7成以内") + "，留现金等今晚PPI、明晚CPI与9月15-16日FOMC。")
D["持仓分析_判断"] = ("把观察窗口放到一年到一年半，" + H(RED, "工行与农行同时踩在补资本与提分红两条线上，估值修复的空间还没有走完") + "，让组合慢慢向4:3:3靠拢是性价比更高的选择；" + H(CYAN, "险资已配2.1万亿红利、仍欠配约1.9万亿") + "，长线资金对高股息的承接尚未结束。" + H(GREEN, "主要风险在美债利率反弹（10Y 4.844%、30Y 5.295%）压制风险偏好，以及市场风格持续偏向成长导致的相对失血") + "；但" + H(ORANGE, "决定A股红利估值锚的是中债10年期1.68%而非美债，国内货币环境仍平稳宽松，这条护城河目前还在") + "。落实到动作：加仓的主线放在工行与农行，招行维持不动，宁波压住不追，江苏与邮储只做小额摊薄，用时间换空间，不追高也不加杠杆——一天的普涨改变不了以年度计的收息逻辑。")
# 占比对比可视化条（现状 vs 目标 4:3:3）：条形长度=占组合比重，数值用高亮 span（不带字号），整体单行注入不增报告行数
_bars = [("国有大行", _ggp, 40.0, "#00d4ff"), ("股份行", _gfp, 30.0, "#ffa657"), ("城商行", _csp, 30.0, "#3fb950")]
_bar_html = ""
for _nm, _cur, _tgt, _col in _bars:
    _d = _cur - _tgt
    _dev = H("#3fb950", "基本达标") if abs(_d) < 1.0 else (H("#ffa657", f"超配 {_d:.0f}pct") if _d > 0 else H("#00d4ff", f"欠配 {abs(_d):.0f}pct"))
    _bar_html += f'<div style="display:flex;align-items:center;gap:10px;margin:7px 0;font-size:12px;"><div style="width:60px;color:var(--text-muted);flex-shrink:0;">{_nm}</div><div style="flex:1;height:14px;background:var(--bg-hover);border-radius:7px;overflow:hidden;"><div style="width:{_cur:.1f}%;height:100%;background:{_col};border-radius:7px;opacity:0.9;"></div></div><div style="width:172px;text-align:right;color:var(--text-secondary);flex-shrink:0;">现状 {H(_col, f"{_cur:.1f}%")} · 目标 {_tgt:.0f}% → {_dev}</div></div>'
D["持仓分析_对比条"] = f'<div style="margin:4px 0 2px;padding:12px 14px;background:var(--bg-secondary);border:1px solid var(--border);border-radius:10px;"><div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">9月9日收盘口径下的权重 vs 目标 4:3:3（条形长度即占组合比重）</div>{_bar_html}</div>'
